'use strict';
const $ = id => document.getElementById(id);
let bootstrap, selected = null, history = [], offset = 0, comparison = false, chartJob = null, chartBusy = false, pollBusy = false, historySignature = null;
const compared = new Set();
const numeric = ['clients','processes','duration','requests','interval','rate','timeout','window_steps','event_limit','history_limit','self_percent'];
const labels = {running:'运行中',cancelling:'正在停止',complete:'本轮样本通过',target_not_met:'本轮样本未达标',failed:'执行失败',interrupted:'已中断',orphaned:'上次未确认结束'};
const element = (tag, text, cls) => {const n=document.createElement(tag); if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;};
async function api(path, body) {
  const options = body === undefined ? {} : {method:'POST',headers:{'Content-Type':'application/json','X-Pressure-Token':bootstrap.token},body:JSON.stringify(body)};
  const response=await fetch(path,options); const result=await response.json();
  if(!response.ok)throw new Error(result.error || `HTTP ${response.status}`);return result;
}
function parameters(){const p={query_id:$('query_id').value,mode:$('mode').value};for(const id of numeric)p[id]=Number($(id).value);return p;}
function preset(){const p=bootstrap.presets[$('profile').value];for(const id of [...numeric,'query_id','mode'])$(id).value=p[id];$('confirmed').checked=false;modeHelp();}
function modeHelp(){for(const id of ['interval','rate','self_percent'])$(id).disabled=(id==='interval'?$('mode').value!=='periodic':id==='rate'?$('mode').value!=='open':$('query_id').value!=='mixed');}
function notice(message){$('formError').textContent=message || '';}
async function check(){notice('');$('check').disabled=true;$('connection').textContent='正在检查连接…';try{const v=await api('/api/check',{url:$('url').value});$('connection').textContent=`连接正常 · ${v.run_id} · 第${v.seq}批 · ${v.queries.length}类查询可用`;}catch(e){$('connection').textContent='连接检查未通过';notice(e.message);}finally{$('check').disabled=false;}}
async function start(){notice('');$('start').disabled=true;try{const v=await api('/api/jobs',{url:$('url').value,profile:$('profile').value,parameters:parameters(),confirmed:$('confirmed').checked});selected=v.id;offset=0;comparison=false;chartJob=null;resetCharts();await poll();}catch(e){notice(e.message);$('start').disabled=false;}}
function metric(id,value,unit=''){const node=$(id);node.textContent=value;if(unit)node.append(element('small',unit));}
function fmt(x){return typeof x==='number'&&Number.isFinite(x)?x.toFixed(2):'—';}
function summaryMetrics(job){const s=job.summary;if(!s || s.status!=='measured'){for(const id of ['mean','p99','maximum','slow','success','failures'])metric(id,'—');return;}
  const groups=Object.values(s.groups);const timed=groups.reduce((n,g)=>n+g.complete_http_json.count,0);
  metric('mean',fmt(timed?groups.reduce((n,g)=>n+(g.complete_http_json.mean_ms||0)*g.complete_http_json.count,0)/timed:null),'ms');
  metric('p99',groups.length===1?fmt(groups[0].complete_http_json.p99_ms):'分类见下表',groups.length===1?'ms':'');
  metric('maximum',fmt(Math.max(...groups.map(g=>g.complete_http_json.max_ms??0))),'ms');
  metric('slow',String(groups.reduce((n,g)=>n+g.complete_http_json.over_500ms,0)));
  metric('success',`${s.outcomes.ok||0} / ${s.planned_arrivals}`);
  metric('failures',String(Object.entries(s.outcomes).reduce((n,[k,v])=>n+(k==='ok'?0:v),0)));
  $('metricScope').textContent='完整HTTP＋JSON解析时间；失败与丢到达保留。混合负载的P99按查询分类展示，不平均分位数。';
}
function table(target,headers,rows){target.classList.remove('empty');const t=element('table'),head=element('thead'),tr=element('tr');headers.forEach(h=>tr.append(element('th',h)));head.append(tr);t.append(head);const body=element('tbody');for(const row of rows){const r=element('tr');for(const v of row)r.append(element('td',v===null?'—':String(v)));body.append(r);}t.append(body);target.replaceChildren(t);}
function classes(job){const s=job.summary;if(!s||s.status!=='measured')return [];return Object.entries(s.groups).map(([name,g])=>{const m=g.complete_http_json;return [new Date(job.started_unix*1000).toLocaleTimeString(),name,m.count,fmt(m.mean_ms),fmt(m.p99_ms),fmt(m.max_ms),m.over_500ms,g.errors_or_drops];});}
function showQualifications(summary){const area=$('qualifications');area.replaceChildren();const flags=[['结构/延迟样本',summary?.all_requests_under_500ms],['服务端并发证据',summary?.server_peak_qualified],['独立来源验真',summary?.independent_source_verified],['百万前缀',summary?.million_prefix_qualified],['持续写查',summary?.continuous_writes_verified]];for(const [text,ok]of flags)area.append(element('span',`${text}：${ok?'通过':'未取得'}`,'chip '+(ok?'good':'')));}
function resetCharts(){for(const id of ['histogram','throughput','latency','outcomes','requestTable','comparison']){$(id).classList.add('empty');$(id).textContent='等待当前实验的已封口记录';}for(const id of ['mean','p99','maximum','slow','success','failures'])metric(id,'—');for(const id of ['page','identity','qualifications','downloads'])$(id).replaceChildren();$('status').textContent='读取实验状态';$('status').className='badge';$('stage').textContent='正在读取所选实验…';$('console').textContent='等待工具输出…';}
async function choose(id){selected=id;offset=0;comparison=false;chartJob=null;resetCharts();await poll();}
function showHistory(){const signature=JSON.stringify(history.map(j=>[j.id,j.state,j.plan.label]))+selected;if(signature===historySignature)return;historySignature=signature;const area=$('history');area.replaceChildren();if(!history.length){area.append(element('p','尚无实验记录','hint'));return;}for(const job of history){const row=element('div',undefined,'historyitem'+(job.id===selected?' active':''));const label=element('label'),box=element('input');box.type='checkbox';box.checked=compared.has(job.id);box.setAttribute('aria-label','比较 '+job.plan.label);box.onchange=()=>{if(box.checked&&compared.size>=3){box.checked=false;notice('最多勾选3个实验');return;}box.checked?compared.add(job.id):compared.delete(job.id);};label.append(box);const button=element('button',job.plan.label);button.append(element('small',`${new Date(job.started_unix*1000).toLocaleString()} · ${labels[job.state]||job.state}`));button.onclick=()=>choose(job.id);row.append(label,button);area.append(row);}}
const ns='http://www.w3.org/2000/svg';
function trend(points){const area=$('latency');area.classList.remove('empty');if(!points.length){area.textContent='没有可用的请求完成时间';return;}const svg=svgNode('svg',{viewBox:'0 0 530 210',role:'img','aria-label':'平均和最大延迟随时间变化'}),max=Math.max(1,...points.map(p=>p.max_ms))*1.15,last=Math.max(1,...points.map(p=>p.second));for(let i=0;i<4;i++){const y=165-i*150/3;svg.append(svgNode('line',{x1:38,y1:y,x2:513,y2:y,stroke:'#2b3f4d'}),svgNode('text',{x:1,y:y+4,fill:'#95aebc','font-size':10},(max*i/3).toFixed(1)));}for(const [key,color]of [['mean_ms','#5bd6c1'],['max_ms','#83b7e8']]){const coords=points.filter(p=>p[key]!==null).map(p=>`${38+p.second/last*475},${165-p[key]/max*150}`).join(' ');svg.append(svgNode('polyline',{points:coords,fill:'none',stroke:color,'stroke-width':2}));for(const p of points){if(p[key]!==null)svg.append(svgNode('circle',{cx:38+p.second/last*475,cy:165-p[key]/max*150,r:3,fill:color}));}}svg.append(svgNode('text',{x:38,y:193,fill:'#95aebc','font-size':10},'0s'),svgNode('text',{x:470,y:193,fill:'#95aebc','font-size':10},`${last}s`));if(max>=500){const y=165-500/max*150;svg.append(svgNode('line',{x1:38,y1:y,x2:513,y2:y,stroke:'#ff8e8b','stroke-dasharray':'4 4'}));}else svg.append(svgNode('text',{x:220,y:193,fill:'#95aebc','font-size':10},'500ms高于当前量程'));area.replaceChildren(svg);}
function svgNode(tag,attrs,text){const n=document.createElementNS(ns,tag);for(const [k,v]of Object.entries(attrs||{}))n.setAttribute(k,String(v));if(text!==undefined)n.textContent=text;return n;}
function bars(id,values,labels,color='#5bd6c1'){const area=$(id);area.classList.remove('empty');const svg=svgNode('svg',{viewBox:'0 0 530 210',role:'img','aria-label':id==='histogram'?'请求延迟分布':'每秒完成请求数'});const max=Math.max(1,...values),left=38,w=475,top=15,h=150;for(let i=0;i<4;i++){const y=top+h-i*h/3;svg.append(svgNode('line',{x1:left,y1:y,x2:left+w,y2:y,stroke:'#2b3f4d'}),svgNode('text',{x:2,y:y+4,fill:'#95aebc','font-size':10},String(Math.round(max*i/3))));}values.forEach((v,i)=>{const width=w/Math.max(values.length,1),bh=h*v/max,x=left+i*width;const rect=svgNode('rect',{x:x+1,y:top+h-bh,width:Math.max(1,width-3),height:Math.max(0,bh),fill:id==='histogram'&&i>=7?'#ff8e8b':color,rx:2});rect.append(svgNode('title',{},`${labels[i]}：${v}`));svg.append(rect);if(values.length<15||i%Math.max(1,Math.floor(values.length/9))===0)svg.append(svgNode('text',{x:x+width/2,y:187,fill:'#95aebc','font-size':9,'text-anchor':'middle'},labels[i]));});area.replaceChildren(svg);}
async function charts(id){if(chartBusy||chartJob===id)return;chartBusy=true;try{const data=await api(`/api/jobs/${id}/charts`);if(selected!==id)return;if(!data.ready){$('histogram').textContent=data.reason;$('throughput').textContent=data.reason;return;}bars('histogram',data.histogram,data.histogram_labels);const last=data.timeline.length?data.timeline[data.timeline.length-1].second:0;if(data.timeline.length){const by=new Map(data.timeline.map(p=>[p.second,p.completed]));const values=Array.from({length:last+1},(_,i)=>by.get(i)||0);bars('throughput',values,values.map((_,i)=>`${i}s`),'#83b7e8');}else $('throughput').textContent='没有可用的请求完成时间';trend(data.timeline);const names=Object.keys(data.outcomes);bars('outcomes',names.map(n=>data.outcomes[n]),names.map(n=>({ok:'成功',http_error:'HTTP错误',transport_error:'网络错误',parse_error:'解析错误',load_generator_busy:'丢到达'}[n]||n)),'#e9bb70');chartJob=id;await requests();}catch(e){notice(e.message);}finally{chartBusy=false;}}
async function requests(){if(!selected)return;const id=selected;const data=await api(`/api/jobs/${id}/requests?offset=${offset}&limit=20&errors=${$('onlyErrors').checked?'1':'0'}`);if(selected!==id)return;if(!data.ready){$('requestTable').textContent=data.reason;return;}table($('requestTable'),['请求编号','客户端','类型','HTTP','结果','端到端ms','排队ms'],data.rows.map(r=>[r.request_id,r.client_id,r.query_class,r.status,r.outcome,fmt(r.chart_ms),fmt(r.queue_ms)]));$('page').textContent=`${data.total?offset+1:0}—${Math.min(offset+20,data.total)} / ${data.total}`;$('previous').disabled=offset===0;$('next').disabled=offset+20>=data.total;}
async function poll(){if(pollBusy)return;pollBusy=true;try{const list=await api('/api/jobs');history=list.jobs;showHistory();const running=history.some(j=>['running','cancelling'].includes(j.state));$('start').disabled=running;if(!selected&&history.length)selected=history[0].id;if(!selected)return;const id=selected,job=await api(`/api/jobs/${id}`);if(id!==selected)return;$('jobTitle').textContent=job.plan.label;$('status').textContent=labels[job.state]||job.state;$('status').className='badge '+job.state;$('stage').textContent=`${job.stage} · 已运行${job.elapsed_seconds.toFixed(1)}秒${job.error?' · '+job.error:''}`;$('busy').classList.toggle('hidden',!['running','cancelling'].includes(job.state));$('identity').textContent=`${job.id} | ${job.url} | ${job.plan.clients}客户端 / ${job.plan.processes}进程 / ${job.plan.mode}${job.summary?.run_id?' | '+job.summary.run_id+' @seq '+job.summary.seq:''}`;$('stop').disabled=job.state!=='running';$('console').textContent=job.console||'等待工具输出…';summaryMetrics(job);showQualifications(job.summary);if(!comparison&&job.summary?.status==='measured')table($('comparison'),['实验时间','查询','有计时样本','平均','P99','最大','>500ms','错误/丢到达'],classes(job));const downloads=$('downloads');downloads.replaceChildren();if(job.summary)for(const [name,label]of [['report.md','中文报告'],['summary.json','摘要JSON'],['analysis.json','原始统计'],['requests.csv','请求CSV'],['experiment.json','实验配置']]){const a=element('a',label);a.href=`/api/jobs/${id}/download?file=${name}`;downloads.append(a);}if(!['running','cancelling'].includes(job.state))await charts(id);}catch(e){notice(e.message);}finally{pollBusy=false;}}
$('check').onclick=check;$('start').onclick=start;$('profile').onchange=preset;$('mode').onchange=modeHelp;$('query_id').onchange=modeHelp;$('refresh').onclick=poll;
$('stop').onclick=async()=>{try{if(selected)await api(`/api/jobs/${selected}/cancel`,{});await poll();}catch(e){notice(e.message);}};
$('previous').onclick=()=>{offset=Math.max(0,offset-20);requests().catch(e=>notice(e.message));};$('next').onclick=()=>{offset+=20;requests().catch(e=>notice(e.message));};$('onlyErrors').onchange=()=>{offset=0;requests().catch(e=>notice(e.message));};
$('compare').onclick=()=>{const jobs=history.filter(j=>compared.has(j.id));const rows=jobs.flatMap(classes);if(!rows.length){notice('请勾选有完整结果的实验');return;}comparison=true;table($('comparison'),['实验时间','查询','有计时样本','平均','P99','最大','>500ms','错误/丢到达'],rows);};
api('/api/bootstrap').then(v=>{bootstrap=v;$('url').value=v.url;$('host').textContent=`发起设备：${v.platform} · Python ${v.python} · ${v.cpu_count??'?'}逻辑核。${v.scope}`;preset();poll();setInterval(poll,2000);}).catch(e=>notice(e.message));
